+      font-weight: 700;
+      letter-spacing: 0.02em;
+      text-transform: uppercase;
+    }
+
+    h1 {
+      margin: 16px 0 10px;
+      font-size: clamp(2.2rem, 4vw, 3.6rem);
+      line-height: 1.05;
+      letter-spacing: -0.04em;
+    }
+
+    .subtitle {
+      margin: 0;
+      max-width: 60ch;
+      font-size: 1.05rem;
+      line-height: 1.7;
+      color: var(--muted);
+    }
+
+    .faq {
+      display: grid;
+      gap: 16px;
+    }
+
+    .example {
+      border: 1px solid var(--card-border);
+      border-radius: var(--radius);
+      background: var(--card);
+      box-shadow: var(--shadow);
+      overflow: hidden;
+    }
+
+    .question {
+      width: 100%;
+      display: flex;
+      align-items: center;
+      justify-content: space-between;
+      gap: 16px;
+      padding: 22px 24px;
+      border: 0;
+      background: transparent;
+      color: inherit;
+      font: inherit;
+      text-align: left;
+      cursor: pointer;
+    }
+
+    .question:focus-visible {
+      outline: 3px solid rgba(107, 124, 255, 0.35);
+      outline-offset: -3px;
+    }
+
+    .question-text {
+      margin: 0;
+      font-size: 1.08rem;
+      line-height: 1.45;
+      font-weight: 700;
+    }
+
+    .icon {
+      flex: 0 0 auto;
+      width: 42px;
+      height: 42px;
+      border-radius: 999px;
+      display: grid;
+      place-items: center;
+      background: rgba(107, 124, 255, 0.12);
+      color: var(--accent-strong);
+      font-size: 1.2rem;
+      font-weight: 800;
+      transition: transform 180ms ease, background 180ms ease;
+    }
+
+    .details {
+      display: grid;
+      grid-template-rows: 0fr;
+      transition: grid-template-rows 220ms ease;
+    }
+
+    .details-inner {
+      overflow: hidden;
+      padding: 0 24px 0;
+      color: var(--muted);
+      line-height: 1.75;
+    }
+
+    .example.open .details {
+      grid-template-rows: 1fr;
+    }
+
+    .example.open .details-inner {
+      padding-bottom: 22px;
+    }
+
+    .example.open .icon {
+      transform: rotate(45deg);
+      background: rgba(79, 99, 255, 0.16);
+    }
+
+    .details p {
+      margin: 0;
+    }
+
+    @media (max-width: 640px) {
+      .page {
+        width: min(100% - 20px, 960px);
+        padding: 20px 0 28px;
+      }
+
+      .hero,
+      .question,
+      .details-inner {
+        padding-left: 18px;
+        padding-right: 18px;
+      }
+
+      .hero {
+        padding-top: 24px;
+        padding-bottom: 24px;
+      }
+
+      .question {
+        padding-top: 18px;
+        padding-bottom: 18px;
+      }
+
+      .question-text {
+        font-size: 1rem;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main class="page">
+    <section class="hero" aria-labelledby="faq-title">
+      <span class="eyebrow">Cat FAQ</span>
+      <h1 id="faq-title">Everything you need to know about cats</h1>
+      <p class="subtitle">
+        Quick answers to common cat questions, designed like a modern product experience.
+      </p>
+    </section>
+
+    <section class="faq" aria-label="Frequently asked questions">
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false">
+          <span class="question-text">Why do cats purr?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details" hidden>
+          <div class="details-inner">
+            <p>Cats often purr when they feel relaxed, but they may also purr when they want comfort or are trying to calm themselves.</p>
+          </div>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false">
+          <span class="question-text">How much sleep do cats need?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details" hidden>
+          <div class="details-inner">
+            <p>Most cats sleep between 12 and 16 hours a day, and kittens or senior cats may rest even more.</p>
+          </div>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false">
+          <span class="question-text">Why do cats knead blankets?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details" hidden>
+          <div class="details-inner">
+            <p>Kneading is a comforting behavior that starts early in life. Adult cats often do it when they're content or marking a safe, familiar space.</p>
+          </div>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false">
+          <span class="question-text">Should indoor cats still get enrichment?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details" hidden>
+          <div class="details-inner">
+            <p>Yes. Scratching posts, window views, puzzle feeders, and play sessions help keep indoor cats mentally and physically active.</p>
+          </div>
+        </div>
+      </div>
+    </section>
+  </main>
+
+  <script>
+    document.querySelectorAll('.example').forEach((example) => {
+      const button = example.querySelector('.question');
+      const details = example.querySelector('.details');
+
+      button.addEventListener('click', () => {
+        const isOpen = example.classList.toggle('open');
+        button.setAttribute('aria-expanded', String(isOpen));
+        details.hidden = !isOpen;
+      });
+    });
+  </script>
+</body>
+</html>
*** End Patch
